### Key tests

```ts
it('tr profile + unsupported X-App-Locale + en Accept-Language → Turkish 400', async () => {
  // seeded: users.preferred_locale = 'tr'
  const res = await app.inject({
    method: 'PATCH', url: '/api/v1/me',
    headers: { authorization: 'Bearer tr-user', 'x-app-locale': 'de', 'accept-language': 'en-US,en;q=0.9' },
    payload: { email: 'not-an-email' },
  });
  expect(res.statusCode).toBe(400);
  expect(res.headers['content-language']).toBe('tr');
  expect(res.json().error.details).toEqual([
    { field: 'email', code: 'INVALID_EMAIL', message: 'Geçerli bir e-posta adresi girin.' },
    { field: 'phone', code: 'REQUIRED', message: 'Bu alan zorunludur.' },
  ]);
  const row = await pool.query('SELECT preferred_locale FROM users WHERE id=$1', [id]);
  expect(row.rows[0].preferred_locale).toBe('tr'); // header did not write the profile
});

it('missing tr key → Turkish generic message, logged, never English', () => {
  const missing: string[] = [];
  const t = createTranslator({ en: catalogs.en, tr: { ...catalogs.tr, 'validation.REQUIRED': undefined } }, 'en', (k) => missing.push(k));
  const { body } = toErrorResponse(
    new AppError('VALIDATION_ERROR', { details: [{ field: 'phone', code: 'REQUIRED' }] }),
    { t, locale: 'tr', requestId: 'r1' });
  expect(missing).toContain('validation.REQUIRED');
  expect(JSON.stringify(body)).not.toMatch(/required|Something went wrong/i);
});
```

### SQL

The only SQL involved is the existing profile lookup, already in `app.ts:97`:

```sql
SELECT preferred_locale FROM users WHERE id = $1;
```

The column itself should be created in a migration like this:

```sql
ALTER TABLE users
  ADD COLUMN preferred_locale text NOT NULL DEFAULT 'en',
  ADD CONSTRAINT users_preferred_locale_fmt CHECK (preferred_locale ~ '^[a-z]{2,3}(-[A-Za-z0-9]+)*$');
```

If the app's supported locales ever shrink, a stored `de` is not an error. It is skipped by the resolver like any other unsupported tag, and the search continues.
